'use strict';

// MODULES //

var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var toWordf = require( '@stdlib/number/float32/base/to-word' );
var ABS_MASK = require( '@stdlib/constants/float32/abs-mask' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var FLOAT32_EXPONENT_BIAS = require( '@stdlib/constants/float32/exponent-bias' );
var FLOAT32_SIGNIFICAND_MASK = require( '@stdlib/constants/float32/significand-mask' );
var fromWordf = require( '@stdlib/number/float32/base/from-word' );
var kernelLog1pf = require( '@stdlib/math/base/special/kernel-log1pf' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var TWO25 = 3.3554432000e+07;                  // 0x4c000000
var IVLN10HI = 4.3432617188e-01;               // 0x3ede6000
var IVLN10LO = -3.1689971365e-05;              // 0xb804ead9
var LOG10_2HI = 3.0102920532e-01;              // 0x3e9a2080
var LOG10_2LO = 7.9034151668e-07;              // 0x355427db
var HIGH_MAX_NORMAL_EXP = 0x7f800000|0;
var HIGH_MIN_NORMAL_EXP = 0x00800000|0;
var HIGH_BIASED_EXP_0 = 0x3f800000|0;


// MAIN //

/**
* Evaluates the common logarithm (base ten) of a single-precision floating-point number.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = log10f( 4.0 );
* // returns ~0.602
*
* @example
* var v = log10f( 8.0 );
* // returns ~0.903
*
* @example
* var v = log10f( 0.0 );
* // returns -Infinity
*
* @example
* var v = log10f( Infinity );
* // returns Infinity
*
* @example
* var v = log10f( NaN );
* // returns NaN
*
* @example
* var v = log10f( -4.0 );
* // returns NaN
*/
function log10f( x ) {
	var hfsq;
	var hx;
	var i;
	var k;
	var y;
	var r;
	var f;

	if ( isnanf( x ) || x < 0.0 ) {
		return NaN;
	}
	x = f32( x );
	hx = toWordf( x ) | 0;
	k = 0;
	if ( hx < HIGH_MIN_NORMAL_EXP ) {
		// Case: x < 2**-126
		if ( ( hx & ABS_MASK ) === 0 ) {
			return NINF;
		}
		k -= 25;

		// Subnormal number, scale up x:
		x = f32( x * TWO25 );
		hx = toWordf( x ) | 0;
	}
	if ( hx >= HIGH_MAX_NORMAL_EXP ) {
		return f32( x + x );
	}
	if ( hx === HIGH_BIASED_EXP_0 ) {
		return 0;
	}
	k += ( ( hx >> 23 ) - FLOAT32_EXPONENT_BIAS ) | 0;
	hx &= FLOAT32_SIGNIFICAND_MASK;
	i = ( ( hx + 0x4afb0d ) & HIGH_MIN_NORMAL_EXP ) | 0;

	// Normalize x or x/2:
	x = fromWordf( hx | ( i ^ HIGH_BIASED_EXP_0 ) );
	k += ( i >> 23 ) | 0;
	y = k;
	f = f32( x - 1.0 );
	hfsq = f32( 0.5 * f32( f * f ) );
	r = kernelLog1pf( f );

	/*
	* Extra precision in for the following member expressions when `float_t` has extra precision (as is the case in JavaScript which uses f64 internally).
	*
	* See: FreeBSD's `e_log10f.c` and `e_log2f.c` for details.
	*/
	return f32( ( ( ( r - hfsq ) + f ) * ( IVLN10LO + IVLN10HI ) ) + ( y * ( LOG10_2LO + LOG10_2HI ) ) ); // eslint-disable-line max-len
}


// EXPORTS //

module.exports = log10f;
